@page "/apply"
@using sv_6f4889b8a47e4d0c8e72621c6b4c8325.Models
@using sv_6f4889b8a47e4d0c8e72621c6b4c8325.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (submittedId is not null)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p class="mb-0">Your application has been received. Your confirmation number is <strong>#@submittedId</strong>.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

        @if (!string.IsNullOrEmpty(submitError))
        {
            <div class="alert alert-danger">@submitError</div>
        }

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="personalInfo"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 2:
                <ReferencesStep References="references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;

            case 3:
                <CoverLetterStep @bind-CoverLetter="coverLetter"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 4:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="coverLetter"
                            IsSubmitting="isSubmitting"
                            OnBack="PreviousStep"
                            OnSubmit="HandleSubmit"
                            OnEditStep="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private bool isSubmitting;
    private int? submittedId;
    private string? submitError;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

::deep .step-indicator {
    counter-reset: step;
    padding: 0;
}

::deep .step-indicator li {
    position: relative;
}

::deep .step-indicator li:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 16px;
    left: 55%;
    width: 90%;
    height: 2px;
    background-color: #dee2e6;
    z-index: 0;
}

::deep .step-indicator li.step-completed:not(:last-child)::after {
    background-color: #198754;
}

::deep .step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    font-size: 0.85rem;
    font-weight: 600;
    position: relative;
    z-index: 1;
}

::deep .last-child-no-border:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

