toolArgs.file_text:
::deep .step-indicator {
    counter-reset: step;
    padding: 0;
}

::deep .step-indicator li {
    position: relative;
}

::deep .step-indicator li:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 16px;
    left: 55%;
    width: 90%;
    height: 2px;
    background-color: #dee2e6;
    z-index: 0;
}

::deep .step-indicator li.step-completed:not(:last-child)::after {
    background-color: #198754;
}

::deep .step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    font-size: 0.85rem;
    font-weight: 600;
    position: relative;
    z-index: 1;
}

::deep .last-child-no-border:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

